css:
.inbox {
  width: 320px;
  margin: 16px;
  padding: 0;
  list-style: none;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
  font-family: system-ui, sans-serif;
}

.mail {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-bottom: 1px solid #e4e4e7;
}

.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #fdba74;
  flex-shrink: 0;
}

.time {
  font-size: 0.8rem;
  color: #71717a;
}

